/// Build a crate with a spec, returns the binary path
pub fn build_crate(crate_name: &str, tspec: Option<&str>, release: bool) -> Result<PathBuf> {
    let workspace = find_workspace_root()?;
    let crate_dir = find_crate_dir(&workspace, crate_name)?;
    let tspec_path = find_tspec(&workspace, &crate_dir, tspec)?;

    let spec = load_spec(&tspec_path)?;
    println!("Building {} with spec {}", crate_name, tspec_path.display());

    let mut cmd = Command::new("cargo");
    cmd.arg("build");
    cmd.arg("-p").arg(crate_name);
    cmd.current_dir(&workspace);

    // Determine profile for binary path
    let is_release = release || spec.cargo.iter().any(|p| matches!(p, CargoParam::Profile(Profile::Release)));

    // Apply spec parameters
    apply_spec_to_command(&mut cmd, &spec, release)?;

    let status = cmd.status().context("failed to run cargo")?;
    if !status.success() {
        bail!("cargo build failed");
    }

    // Return binary path
    let profile_dir = if is_release { "release" } else { "debug" };
    Ok(workspace.join("target").join(profile_dir).join(crate_name))
}

/// Build and run a crate with a spec
pub fn run_crate(crate_name: &str, tspec: Option<&str>, release: bool) -> Result<()> {
    let binary = build_crate(crate_name, tspec, release)?;

    println!("Running {}", binary.display());
    let status = Command::new(&binary)
        .status()
        .with_context(|| format!("failed to run {}", binary.display()))?;

    if !status.success() {
        if let Some(code) = status.code() {
            bail!("{} exited with code {}", crate_name, code);
        } else {
            bail!("{} terminated by signal", crate_name);
        }
    }

    Ok(())
}

