}

/// Find the tspec for a crate - either explicit path or default tspec.toml
pub fn find_tspec(_workspace: &Path, crate_dir: &Path, explicit: Option<&str>) -> Result<PathBuf> {
    match explicit {
        Some(path) => {
            // Try as absolute or relative path
            let p = PathBuf::from(path);
            if p.exists() {
                return Ok(p);
            }
