You're right - I should have build.rs read from tspec.toml so it remains the source of truth.

The approach:
1. Add `toml` as a build-dependency
2. build.rs reads tspec.toml, parses linker args
3. Emits `cargo:rustc-link-arg-bin=ex-x2-xt=<arg>` for each

```rust
// build.rs
use std::fs;

fn main() {
    let tspec = fs::read_to_string("tspec.toml").expect("tspec.toml");
    let parsed: toml::Value = toml::from_str(&tspec).expect("parse tspec");

    if let Some(linkers) = parsed.get("linker").and_then(|l| l.as_array()) {
        for linker in linkers {
            if let Some(args) = linker.get("args").and_then(|a| a.as_array()) {
                for arg in args {
                    if let Some(s) = arg.as_str() {
                        println!("cargo:rustc-link-arg-bin=ex-x2-xt={}", s);
                    }
                }
            }
        }
    }
}
```

