use anyhow::{Context, Result, bail};
use std::fs;
use std::path::Path;
use std::process::Command;

use crate::find_paths::{find_crate_dir, find_tspec, find_workspace_root};
use crate::tspec::load_spec;
use crate::types::{CargoParam, LinkerParam, Profile, RustcParam, Spec};

/// Build a crate with a spec
pub fn build_crate(crate_name: &str, tspec: Option<&str>, release: bool) -> Result<()> {
    let workspace = find_workspace_root()?;
    let crate_dir = find_crate_dir(&workspace, crate_name)?;
    let tspec_path = find_tspec(&crate_dir, tspec)?;

    let mut cmd = Command::new("cargo");
    cmd.arg("build");
    cmd.arg("-p").arg(crate_name);
    cmd.current_dir(&workspace);

    // Track if we generated a build.rs
    let mut generated_build_rs = false;
    let build_rs_path = crate_dir.join("build.rs");

    // Apply spec if present, otherwise plain cargo build
    if let Some(path) = &tspec_path {
        let spec = load_spec(path)?;
        println!("Building {} with spec {}", crate_name, path.display());

        // Generate temporary build.rs for linker flags if needed
        if !spec.linker.is_empty() && !build_rs_path.exists() {
            generate_build_rs(&build_rs_path, crate_name, &spec)?;
            generated_build_rs = true;
        }

        apply_spec_to_command(&mut cmd, &spec, release)?;
    } else {
        println!("Building {} (no tspec)", crate_name);
        if release {
            cmd.arg("--release");
        }
    }

    let status = cmd.status().context("failed to run cargo")?;

    // Clean up generated build.rs
    if generated_build_rs {
        let _ = fs::remove_file(&build_rs_path);
    }

    if !status.success() {
        bail!("cargo build failed");
    }

    Ok(())
}

/// Generate a temporary build.rs with scoped linker flags
fn generate_build_rs(path: &Path, crate_name: &str, spec: &Spec) -> Result<()> {
    let mut lines = vec![
        "// Generated by xt - do not edit".to_string(),
        "fn main() {".to_string(),
    ];

    for param in &spec.linker {
        match param {
            LinkerParam::Args(args) => {
                for arg in args {
                    lines.push(format!(
                        "    println!(\"cargo:rustc-link-arg-bin={}={}\");",
                        crate_name, arg
                    ));
                }
            }
            LinkerParam::Static => {
                lines.push(format!(
                    "    println!(\"cargo:rustc-link-arg-bin={}=-static\");",
                    crate_name
                ));
            }
            LinkerParam::NoStdlib => {
                lines.push(format!(
                    "    println!(\"cargo:rustc-link-arg-bin={}=-nostdlib\");",
                    crate_name
                ));
            }
            LinkerParam::Entry(entry) => {
                lines.push(format!(
                    "    println!(\"cargo:rustc-link-arg-bin={}=-e{}\");",
                    crate_name, entry
                ));
            }
            LinkerParam::GcSections => {
                lines.push(format!(
                    "    println!(\"cargo:rustc-link-arg-bin={}=-Wl,--gc-sections\");",
                    crate_name
                ));
            }
        }
    }

    lines.push("}".to_string());

    fs::write(path, lines.join("\n")).context("failed to write build.rs")?;
    Ok(())
}

